# z-image — generated by tools/gen_model_py.py from the yaml
# cascade (2026-09-02 flip), then hand-edited since. The
# class IS the unit: family head → variants → quant cells;
# merged_defaults() walks the cascade. Parity pinned by
# tests/walls/suites/test_python_models.py + the http goldens.
#
# SSOT law: this file REPLACES model.yaml + variants/. A
# model.yaml reappearing next to it is a LOUD refusal.
#
# BOARDED to the image-gen card (2026-09-05 — the unboarded
# "data family" era retired by operator order: every offered
# model runs; nothing is offered that cannot compose). The
# family's graph variance rides lane_inputs: the AuraFlow
# sampling shift (z-image is a lumina2-flow DiT) and the
# qwen-3 4b text encoder.


from melite_models import  KnobRow,Model, Variant, Cell, LaneInputs, Genre, ClipType


class ZImage(Model):
    id = 'z-image'
    genre = Genre.IMAGE
    label = 'Z-Image'
    description = 'Fast Z-Image / Z-Image Turbo text-to-image generation.'
    form = 'form_generate'
    engine = 'comfyui'
    card = 'image-gen'           # the owning card (cross-validation hook)
    # No mods — the lora catalog is empty for this family today (mods
    # are model-level declarations; the loras channel is closed).
    # core tuning — the Comfy-Org z_image_turbo official template:
    # 8-step, CFG 1, res_multistep/simple
    defaults = dict(
            scheduler='simple',
            width=1024,
            height=1024,
            steps=8,
            sampler='res_multistep',
            cfg=1.0,
            negative_prompt=None,
        )
    # the cascade as frozen rows (PYTHON SHAPE LAW rung 1). ONE
    # variant: turbo — the provisioned checkpoint (int8 convrot on
    # the mount). The 50-step base checkpoint is not provisioned;
    # a variant without weights is an offer that cannot run.
    variants = (
        Variant(id='turbo', label='Turbo', hint='8-step distilled — fast (DEFAULT)', route='z-image', order=0, cells=(
                    Cell(quant='int8', label='INT8 ConvRot', route='z-image-int8', vram_peak_gb=14.0),
        )),
    )
    # loader stack — the weight facts the card renderer reads (the
    # unet basename stated ONCE; no artifact row exists for it)
    lane_inputs = LaneInputs(
        unet='z_image_turbo_int8_convrot.safetensors',
        text_encoder='qwen_3_4b.safetensors',
        clip_type=ClipType.LUMINA2,
        vae='ae.safetensors',
        sampling_shift=3.0,
        latent_node='EmptySD3LatentImage',
    )

    # the image-gen card surface (row 3, 2026-09-06 — same targets as
    # krea-2: the shared image_t2i renderer; the flow-shift wrapper
    # sits ABOVE the sampler, never between a knob and its node).
    card_knobs = (
        KnobRow(card='prompt', inject='CLIPTextEncode.0.text', kind='s'),
        KnobRow(card='negative_prompt', inject='CLIPTextEncode.1.text', kind='s'),
        KnobRow(card='width', inject='EmptySD3LatentImage.0.width', kind='n'),
        KnobRow(card='height', inject='EmptySD3LatentImage.0.height', kind='n'),
        KnobRow(card='seed', inject='KSampler.0.seed', kind='n'),
        KnobRow(card='steps', inject='KSampler.0.steps', kind='n'),
        KnobRow(card='cfg', inject='KSampler.0.cfg', kind='n'),
        KnobRow(card='sampler', inject='KSampler.0.sampler_name', kind='s'),
        KnobRow(card='scheduler', inject='KSampler.0.scheduler', kind='s'),
    )
